// src/data/resume.json is generated by scripts/parse-resume.mjs before every build. Never edit it by hand.
import data from '../data/resume.json';

export type Segment = { text: string; bold?: boolean; href?: string };
export type RichText = Segment[];
export type Role = { title: string; start: string; end: string | null; summary: RichText[]; highlights: RichText[] };
export type Company = { company: string; location: string | null; roles: Role[] };
export type Education = { institution: string; degree: string | null; start: string; end: string | null; highlights: RichText[] };
export type Resume = {
  basics: { name: string; city: string; email: string; linkedin: string; website: string };
  introduction: RichText[];
  skills: { label: string; items: string[] }[];
  education: Education[];
  experience: Company[];
};

export const resume = data as Resume;

export const plain = (rich: RichText) => rich.map((s) => s.text).join('');

const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

/** "2023-01" → "Jan 2023", "2013" → "2013", null → "now". */
export function formatYm(ym: string | null): string {
  if (!ym) return 'now';
  const [y, m] = ym.split('-');
  return m ? `${MONTHS[Number(m) - 1]} ${y}` : y;
}

/** "Mar 2022 — Dec 2022", "Jan 2023 — now": both ends always carry their year. */
export const roleDates = (role: Pick<Role, 'start' | 'end'>) => `${formatYm(role.start)} — ${formatYm(role.end)}`;

/** A company's span in years: "2022 — now", "2013 — 2018". */
export function companyYears(company: Company): string {
  const starts = company.roles.map((r) => r.start.slice(0, 4));
  const current = company.roles.some((r) => r.end === null);
  const ends = company.roles.map((r) => (r.end ?? '').slice(0, 4)).filter(Boolean);
  const first = starts.sort()[0];
  const last = current ? 'now' : ends.sort().at(-1)!;
  return first === last ? first : `${first} — ${last}`;
}

export const currentRole = resume.experience[0].roles[0];
export const currentCompany = resume.experience[0];
